/* ================= helpers ================= */
function $(id){ return document.getElementById(id); }
function esc(s){ return String(s==null?'':s).replace(/[&<>"']/g, function(c){ return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]; }); }
function uid(){ return Date.now().toString(36) + Math.random().toString(36).slice(2,8); }
function fmtVND(n){ if(n==null||n===''||isNaN(n)) return ''; try{ return new Intl.NumberFormat('vi-VN').format(Math.round(Number(n)*100)/100)+' đ'; }catch(e){ return n+' đ'; } }
function fmtDate(ts){ var d=new Date(ts); return String(d.getDate()).padStart(2,'0')+'/'+String(d.getMonth()+1).padStart(2,'0')+'/'+d.getFullYear(); }
function fmtDateTime(ts){ var d=new Date(ts); return fmtDate(ts)+' '+String(d.getHours()).padStart(2,'0')+':'+String(d.getMinutes()).padStart(2,'0'); }
function toast(msg, type){
  var box=$('toast'), el=document.createElement('div');
  el.className='toast'+(type?' '+type:''); el.textContent=msg; box.appendChild(el);
  setTimeout(function(){ el.classList.add('show'); },10);
  setTimeout(function(){ el.classList.remove('show'); setTimeout(function(){ el.remove(); },250); }, 3600);
}
function download(name, blob){
  var a=document.createElement('a'); a.href=URL.createObjectURL(blob); a.download=name;
  document.body.appendChild(a); a.click(); a.remove();
  setTimeout(function(){ URL.revokeObjectURL(a.href); },2000);
}
function copyText(t, label){
  var msg = label || ('Đã sao chép: '+t);
  try{
    if(navigator.clipboard && navigator.clipboard.writeText){ navigator.clipboard.writeText(t); toast(msg,'ok'); return; }
  }catch(e){}
  try{
    var ta=document.createElement('textarea'); ta.value=t; document.body.appendChild(ta); ta.select();
    document.execCommand('copy'); ta.remove(); toast(msg,'ok');
  }catch(e){ toast('Không sao chép được — chọn thủ công.','err'); }
}

/* ================= state & storage ================= */
var storageOk = true;
try{ localStorage.setItem('__t','1'); localStorage.removeItem('__t'); }catch(e){ storageOk=false; }
var memStore = {};
function rawGet(k){ if(storageOk) return localStorage.getItem(k); return memStore[k]||null; }
function rawSet(k,v){ if(storageOk) localStorage.setItem(k,v); else memStore[k]=v; }

function isObj(v){ return !!v && Object.prototype.toString.call(v)==='[object Object]'; }
function safeText(v){ return v==null?'':String(v); }
function safeNumber(v, fallback){ var n=Number(v); return Number.isFinite(n)?n:(fallback==null?0:fallback); }
function safeId(v){ var s=safeText(v); return /^[A-Za-z0-9_-]{1,80}$/.test(s)?s:uid(); }
function safePlain(v, depth){
  depth=depth||0;
  if(depth>12) throw new Error('Dữ liệu sao lưu lồng quá sâu.');
  if(v==null || typeof v==='string' || typeof v==='boolean') return v;
  if(typeof v==='number'){ if(!Number.isFinite(v)) throw new Error('Dữ liệu có số không hợp lệ.'); return v; }
  if(Array.isArray(v)) return v.map(function(x){ return safePlain(x,depth+1); });
  if(isObj(v)){
    var out={};
    Object.keys(v).forEach(function(k){
      if(k==='__proto__'||k==='prototype'||k==='constructor') return;
      out[k]=safePlain(v[k],depth+1);
    });
    return out;
  }
  throw new Error('Dữ liệu sao lưu có kiểu không hợp lệ.');
}
function normalizeAI(ai){
  if(!isObj(ai)||!isObj(ai.tong_hop)||!Array.isArray(ai.docs)) throw new Error('Kết quả AI không hợp lệ.');
  var out={tong_hop:safePlain(ai.tong_hop),docs:[]};
  ai.docs.forEach(function(dc){
    if(!isObj(dc)||!isObj(dc.fields)||!Array.isArray(dc.rules)) throw new Error('Chứng từ trong kết quả AI không hợp lệ.');
    out.docs.push({
      ten_file:safeText(dc.ten_file),
      loai:['PO','PR','HOADON','BBBG','BAOGIA','HOPDONG','UNC','PHIEUTHU','KHAC'].indexOf(dc.loai)>=0?dc.loai:'KHAC',
      fields:safePlain(dc.fields),
      rules:dc.rules.map(function(r){
        if(!isObj(r)||['dat','loi','xem'].indexOf(r.trang_thai)<0) throw new Error('Rule trong kết quả AI không hợp lệ.');
        return {id:safeText(r.id),ten:safeText(r.ten),trang_thai:r.trang_thai,chi_tiet:safeText(r.chi_tiet)};
      })
    });
  });
  return out;
}
function normalizeAccounting(accounting){
  if(!isObj(accounting)) throw new Error('Dữ liệu hạch toán trong bản sao lưu không hợp lệ.');
  var options=[];
  if(accounting.options!=null){
    if(!Array.isArray(accounting.options)) throw new Error('Danh sách tài khoản trong bản sao lưu không hợp lệ.');
    options=accounting.options.map(function(option){
      if(!isObj(option)) throw new Error('Tài khoản trong bản sao lưu không hợp lệ.');
      return {code:safeText(option.code),name:safeText(option.name)};
    });
  }
  return {
    c1:safeText(accounting.c1)||'01',
    cc:safeText(accounting.cc)||'0000',
    acc:safeText(accounting.acc),
    product:safeText(accounting.product)||'000',
    c5:safeText(accounting.c5)||'000',
    c6:safeText(accounting.c6)||'01',
    ic:safeText(accounting.ic)||'01',
    options:options,
    locked:!!accounting.locked,
    note:safeText(accounting.note),
    manual:!!accounting.manual
  };
}
function normalizeMapping(mapping){
  if(mapping==null) return null;
  if(!isObj(mapping)||!isObj(mapping.accounts)) throw new Error('Mapping trong bản sao lưu không hợp lệ.');
  var accounts={};
  Object.keys(mapping.accounts).forEach(function(rawKey){
    var key=safeText(rawKey).toUpperCase();
    if(!/^[A-Z][A-Z0-9]{1,20}$/.test(key)) throw new Error('Budget code trong mapping không hợp lệ.');
    var rows=mapping.accounts[rawKey];
    if(!Array.isArray(rows)) throw new Error('Danh sách tài khoản trong mapping không hợp lệ.');
    accounts[key]=rows.map(function(row){
      if(!isObj(row)) throw new Error('Dòng tài khoản trong mapping không hợp lệ.');
      var code=safeText(row.c!=null?row.c:row.code);
      if(!/^\d{8}$/.test(code)) throw new Error('Mã tài khoản trong mapping không hợp lệ.');
      return {c:code,n:safeText(row.n!=null?row.n:row.name)};
    });
  });
  var ic=[];
  if(mapping.ic!=null){
    if(!Array.isArray(mapping.ic)) throw new Error('Danh sách interco trong mapping không hợp lệ.');
    ic=mapping.ic.map(function(row){
      if(!isObj(row)) throw new Error('Dòng interco trong mapping không hợp lệ.');
      var code=safeText(row.code);
      if(!/^\d{1,2}$/.test(code)) throw new Error('Mã interco trong mapping không hợp lệ.');
      return {code:code.padStart(2,'0'),name:safeText(row.name)};
    });
  }
  return {accounts:accounts,ic:ic};
}
function normalizeState(raw){
  if(!isObj(raw)||!Array.isArray(raw.sets)) throw new Error('State không hợp lệ.');
  var used=Object.create(null);
  var sets=raw.sets.map(function(s){
    if(!isObj(s)) throw new Error('Bộ chứng từ không hợp lệ.');
    var id=safeId(s.id); while(used[id]) id=uid(); used[id]=1;
    var out={
      id:id, createdAt:safeNumber(s.createdAt,Date.now()), updatedAt:safeNumber(s.updatedAt,Date.now()),
      eform:safeText(s.eform), type:'PO/PR', isInv:!!s.isInv, itemNumber:safeText(s.itemNumber),
      payee:s.payee==='NV'?'NV':'NCC', vendor:safeText(s.vendor),
      files:Array.isArray(s.files)?s.files.map(function(f){
        if(!isObj(f)) throw new Error('Metadata file không hợp lệ.');
        return {name:safeText(f.name),size:Math.max(0,safeNumber(f.size,0))};
      }):[]
    };
    if(s.checkedAt!=null) out.checkedAt=safeNumber(s.checkedAt,0);
    if(s.ai!=null) out.ai=normalizeAI(s.ai);
    if(s.accounting!=null) out.accounting=normalizeAccounting(s.accounting);
    if(s.termManual!=null) out.termManual=safeText(s.termManual);
    if(isObj(s.decision)&&['APPROVED','SUPPLEMENT'].indexOf(s.decision.status)>=0){
      out.decision={status:s.decision.status,note:safeText(s.decision.note),at:safeNumber(s.decision.at,Date.now())};
    }
    return out;
  });
  return {sets:sets,mapping:normalizeMapping(raw.mapping)};
}

var state = load();
function load(){
  try{
    var d = JSON.parse(rawGet(LS_KEY));
    if(d && Array.isArray(d.sets)) return normalizeState(d);
  }catch(e){}
  return {sets:[],mapping:null};
}
function persist(){ try{ rawSet(LS_KEY, JSON.stringify({sets:state.sets,mapping:state.mapping})); }catch(e){ toast('Không lưu được dữ liệu: '+e.message,'err'); } }
persist(); /* migrate state cũ và loại bỏ cấu hình AI khỏi localStorage */
function findSet(id){ for(var i=0;i<state.sets.length;i++) if(state.sets[i].id===id) return state.sets[i]; return null; }

