$('fileMap').addEventListener('change', function(e){
  var f=e.target.files[0]; e.target.value='';
  if(!f) return;
  var isCsv=/\.csv$/i.test(f.name);
  var reader=new FileReader();
  reader.onload=function(ev2){
    try{
      if(!isCsv && typeof XLSX!=='undefined'){
        var wb=XLSX.read(new Uint8Array(ev2.target.result),{type:'array'});
        importMapping(XLSX.utils.sheet_to_json(wb.Sheets[wb.SheetNames[0]],{header:1,raw:false,defval:''}));
        var icSheet=wb.SheetNames.find(function(n){return /^ic$/i.test(n.trim());});
        if(icSheet) importICSheet(XLSX.utils.sheet_to_json(wb.Sheets[icSheet],{header:1,raw:false,defval:''}));
      }else if(isCsv){
        var text=ev2.target.result;
        if(text.charCodeAt(0)===0xFEFF) text=text.slice(1);
        var rows=[],row=[],cur='',q=false;
        for(var i=0;i<text.length;i++){var ch=text[i];
          if(q){ if(ch==='"'){ if(text[i+1]==='"'){cur+='"';i++;} else q=false; } else cur+=ch; }
          else{ if(ch==='"')q=true; else if(ch===','){row.push(cur);cur='';} else if(ch==='\n'||ch==='\r'){ if(ch==='\r'&&text[i+1]==='\n')i++; row.push(cur);rows.push(row);row=[];cur=''; } else cur+=ch; } }
        if(cur!==''||row.length){row.push(cur);rows.push(row);}
        importMapping(rows.filter(function(r){return r.some(function(c){return String(c).trim()!=='';});}));
      }else{ toast('Không tải được thư viện Excel — hãy dùng file CSV.','err'); }
    }catch(err){ toast('Lỗi đọc file mapping: '+err.message,'err'); }
  };
  if(isCsv) reader.readAsText(f,'utf-8'); else reader.readAsArrayBuffer(f);
});
$('btnWipe').addEventListener('click', function(){
  if(!window.confirm('Xóa TOÀN BỘ dữ liệu (bộ chứng từ và mapping)? Nên Sao lưu trước.')) return;
  state={sets:[],mapping:null};
  persist(); $('settingsModal').classList.remove('on'); showView('list');
  toast('Đã xóa toàn bộ dữ liệu.');
});
$('btnExport').addEventListener('click', exportExcel);
$('btnBackup').addEventListener('click', backup);
$('btnRestore').addEventListener('click', function(){ $('fileRestore').click(); });
$('fileRestore').addEventListener('change', function(e){
  var f=e.target.files[0]; e.target.value='';
  if(!f) return;
  var reader=new FileReader();
  reader.onload=function(ev2){
    try{
      var d=JSON.parse(ev2.target.result);
      if(!d||d.app!=='vng-ap-doccheck'||!d.state) throw new Error('Sai định dạng file sao lưu.');
      var st=normalizeState(d.state); /* chấp nhận bản v1 nhưng tự loại cấu hình AI cũ */
      if(!window.confirm('Phục hồi '+st.sets.length+' bộ chứng từ? Dữ liệu hiện tại ('+state.sets.length+' bộ) sẽ bị thay thế.')) return;
      state=st; persist(); showView('list');
      toast('Đã phục hồi '+state.sets.length+' bộ chứng từ.','ok');
    }catch(err){ toast('Lỗi đọc file sao lưu: '+err.message,'err'); }
  };
  reader.readAsText(f,'utf-8');
});

